import { by, skip } from '../../lib/appium.mjs';
import { requireExpert, openExpert, assertTextRtl } from '../../lib/expert.mjs';

export const name = '«חוקי זיהוי» → «גרסאות קודמות»: пояснения прежних версий («QA 15.11 בדיקה…»), начинающиеся с латиницы, показаны в RTL #7581cb @iphone @app @prod-safe';

export default async function (app) {
  requireExpert();
  await openExpert(app);

  await app.scrollTo(by.exact('גרסאות קודמות'), { max: 20, what: 'раздел «גרסאות קודמות»' });
  let first;
  try {
    first = await app.scrollTo(by.begins('QA 15.11 בדיקה'), { max: 12, what: 'пояснение «QA 15.11 בדיקה…» в «גרסאות קודמות»' });
  } catch {
    skip('в «גרסאות קודמות» нет версий с пояснением «QA 15.11 בדיקה…» (версии 15.11 — данные аккаунта jleprog34); проверить вручную на любой версии с латиницы в начале');
  }
  const visible = await app.findAll(by.begins('QA 15.11 בדיקה'));
  for (const el of visible.slice(0, 3)) {
    await assertTextRtl(app, el, `пояснение версии «${String(await el.attr('name')).slice(0, 25)}»`);
  }
  void first;
}
